solution_files.TwoFer.class.st:
"
I say who gets a cookie.
"
Class {
	#name : #TwoFer,
	#superclass : #Object,
	#category : #'Exercise@TwoFer'
}

{ #category : #accessing }
TwoFer >> who [
	^ self who: 'you'
]

{ #category : #accessing }
TwoFer >> who: aName [
	"Join the parts."
	^ 'One for ', aName, ', one for me.'
]

